using System.ComponentModel.DataAnnotations;
namespace ModelViews.Operations;

public record RescheduleRequest(int CourtId, int SlotId, DateOnly Date, [Required, StringLength(500, MinimumLength = 5)] string Reason);
public record BatchBookingRequest(int CourtId, DateOnly FirstDate, int[] SlotIds, int Weeks, int PlayerCount, int? GroupId, [Required, StringLength(60)] string RequestKey, int? ExpectedTotal = null);
public record DeskBookingRequest(int CustomerId, int CourtId, int SlotId, DateOnly Date, int PlayerCount, [Required, StringLength(60)] string RequestKey);
public record BookingCaseRequest([Required] string Kind, [Required, StringLength(2000, MinimumLength = 5)] string Reason);
public record ResolutionRequest(bool Accepted, [Required, StringLength(2000, MinimumLength = 5)] string Resolution);
public record CaseView(int Id, int BookingId, string Kind, string Reason, string Status, string? Resolution, DateTime CreatedAt);
public record HistoryView(string Event, string Detail, DateTime At);
public record CalendarEntry(int Id, string Code, int CourtId, string Court, DateOnly Date, string Start, string End, string Status, bool CheckedIn, string Customer);
public record AlternativeSlot(int CourtId, string Court, int SlotId, DateOnly Date, string Label, int Price);
public record InboxView(int Id, int? BookingId, string Title, string Body, DateTime CreatedAt, DateTime? ReadAt);
public record PreferenceView(bool RemindersEnabled, int MinutesBefore, bool Email, bool Sms, bool Zalo);
public record DeliveryView(int Id, int? BookingId, string Channel, string Status, string? Error, DateTime CreatedAt, DateTime? LastAttempt, int Attempts);
public record IncidentRequest(int BranchId, int? CourtId, DateOnly Date, int? SlotId, [Required, StringLength(1500, MinimumLength = 5)] string Message, [Required, StringLength(60)] string RequestKey);
public record ContactOutcomeRequest([Required, StringLength(1500, MinimumLength = 5)] string Outcome);
public record DisruptionView(int Id, int BookingId, string Code, string Customer, string Message, DateTime? ContactedAt, string? Outcome);
public record ShiftRequest(int BranchId, int StaffId, DateTime StartsAtUtc, DateTime EndsAtUtc, [StringLength(500)] string Note);
public record ShiftView(int Id, int BranchId, int StaffId, string StaffName, DateTime StartsAtUtc, DateTime EndsAtUtc, string Note);
public record HandoverRequest(int BranchId, [Required, StringLength(2000, MinimumLength = 5)] string Text);
public record HandoverView(int Id, int BranchId, string Text, int CreatedBy, DateTime CreatedAt, DateTime? ClosedAt, string? Resolution);
public record PrivacyRequestDto([Required] string Kind, [Required, StringLength(2000, MinimumLength = 5)] string Detail);
public record PrivacyView(int Id, int UserId, string Kind, string Detail, string Status, string? Resolution, DateTime CreatedAt);
public record ReviewReportRequest([Required, StringLength(1500, MinimumLength = 5)] string Reason);
public record ReviewModerationRequest(bool Hide, [Required, StringLength(1500, MinimumLength = 5)] string Reason);
public record ReviewReportView(int Id, int ReviewId, string Reason, string Status, string? Resolution, string? Comment, int Rating);
public record ReviewReplyRequest([Required, StringLength(2000, MinimumLength = 2)] string Text);
public record ReviewReplyView(int Id, int ReviewId, string Text, DateTime CreatedAt, DateTime? UpdatedAt);
public record MediaView(int Id, string Url, string ContentType, long Length);
public record RsvpView(int UserId, string Name, bool? Attending);
public record FavoriteView(int CourtId, int BranchId, string CourtName);
public record CustomerInsights(int Customers, int NewCustomers, int ReturningCustomers, int Bookings, int NoShows, decimal NoShowRate, int Waiting, int Promoted);
public record DeskCustomerView(int Id, string Name, bool IsVerified);
public record ShiftStaffView(int Id, string Name, int? BranchId);
public record GroupMeetingView(int Id, string Code, string Date, string Slot, int OwnerId, int PlayerCount);
